import{_ as p,c as t,a2 as h,o as i}from"./chunks/framework.CqbvlPrP.js";const d=JSON.parse('{"title":"第二章 内心生起哪三种念想会让自己受到伤害？","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/2第二章 内心生起哪三种念想会让自己受到伤害.md","filePath":"meditation/巴利文大藏经/2第二章 内心生起哪三种念想会让自己受到伤害.md"}'),o={name:"meditation/巴利文大藏经/2第二章 内心生起哪三种念想会让自己受到伤害.md"};function s(n,a,e,m,r,j){return i(),t("div",null,a[0]||(a[0]=[h('<h1 id="第二章-内心生起哪三种念想会让自己受到伤害" tabindex="-1">第二章 内心生起哪三种念想会让自己受到伤害？ <a class="header-anchor" href="#第二章-内心生起哪三种念想会让自己受到伤害" aria-label="Permalink to &quot;第二章 内心生起哪三种念想会让自己受到伤害？&quot;">​</a></h1><p>完全读懂巴利文大藏经</p><p>相应部3相应2经/男子经(憍萨罗相应/有偈篇/祇夜)</p><p>有个时候，骄萨罗国的波斯匿王来到佛陀的住所，顶礼佛陀后，波斯匿王在一旁坐下，他问佛陀：“世尊，当人的内心生起什么的时候，就会对自己不利，让自己产生痛苦，无法安乐？”</p><p>佛陀说：“大王，当人的内心生起了三种念想的时候，就会对自己不利，让自己产生痛苦，无法安乐，是哪三种念想呢？</p><p>大王，当人内心生起贪欲念想的时候，就会对自己不利，让自己产生痛苦，无法安乐；</p><p>当人内心生起愤怒念想的时候，就会对自己不利，让自己产生痛苦，无法安乐；</p><p>当人内心不明白世间的真相，愚昧无知，没有智慧，错乱因果的时候，就会对自己不利，让自己产生痛苦，无法安乐。</p><p>大王，当人内心生起贪欲、愤怒、愚痴这三种念想的时候，就会对自己不利，让自己产生痛苦，无法安乐。这些生起贪欲、愤怒、愚痴念想的人就如同果树长出的果实太多，引来无数的人争相折枝采摘果实，反而让果树本身由于树枝被折断受到伤害。”</p><p>这时，佛陀说偈言：</p><p>「贪与嗔及痴，生此恶心已。</p><p>此为自伤害，如折果树枝。」</p><p>巴利语原版经文</p><p>SN.3.2/(2). Purisasuttaṃ</p><p>113. Sāvatthinidānaṃ. Atha kho rājā pasenadi kosalo yena bhagavā tenupasaṅkami; upasaṅkamitvā bhagavantaṃ abhivādetvā ekamantaṃ nisīdi. Ekamantaṃ nisinno kho rājā pasenadi kosalo bhagavantaṃ etadavoca– “kati nu kho, bhante, purisassa dhammā ajjhattaṃ uppajjamānā uppajjanti ahitāya dukkhāya aphāsuvihārāyā”ti?</p><p>“Tayo kho, mahārāja, purisassa dhammā ajjhattaṃ uppajjamānā uppajjanti ahitāya dukkhāya aphāsuvihārāya. Katame tayo? Lobho kho, mahārāja, purisassa dhammo ajjhattaṃ uppajjamāno uppajjati ahitāya dukkhāya aphāsuvihārāya. Doso kho, mahārāja, purisassa dhammo ajjhattaṃ uppajjamāno uppajjati ahitāya dukkhāya aphāsuvihārāya. Moho kho, mahārāja, purisassa dhammo ajjhattaṃ uppajjamāno uppajjati ahitāya dukkhāya aphāsuvihārāya Ime kho, mahārāja, tayo purisassa dhammā ajjhattaṃ uppajjamānā uppajjanti ahitāya dukkhāya aphāsuvihārāyā”ti. Idamavoca …pe…</p><p>“Lobho doso ca moho ca, purisaṃ pāpacetasaṃ;</p><p>Hiṃsanti attasambhūtā, tacasāraṃva samphalan”ti.</p>',18)]))}const _=p(o,[["render",s]]);export{d as __pageData,_ as default};
